INSERT INTO public.manuais (slug, titulo, descricao, tipo, publicado, conteudo)
VALUES (
  'guia-uso-gerencial',
  'Guia de Uso Gerencial',
  'Primeiros passos · Trilha interativa em 8 etapas para gestores, diretores e administradores.',
  'trilha',
  true,
  '{"subtitulo":"Siga a trilha para transformar informações comerciais em decisões, prioridades e ações.","resumo":"Uma boa gestão comercial começa pela compreensão do contexto, avança pela análise dos resultados e se completa quando os aprendizados são transformados em ações. Esta trilha mostra o caminho recomendado para utilizar o Imersão Comercial de forma gerencial.","publico_alvo":"Gestores, diretores e administradores","pre_requisitos":["Acesso à plataforma com perfil gerencial"],"secoes":[{"titulo":"1. Entrevistas","texto":"Comece entendendo o contexto antes de analisar os números.","passos":["Leia individualmente as entrevistas dos representantes.","Observe temas recorrentes, dificuldades e oportunidades."],"dicas":["Decisão esperada: definir quais pontos merecem aprofundamento."]},{"titulo":"2. Visão REP","texto":"Transforme o conteúdo da entrevista em uma leitura estruturada de cada representante.","passos":["Leia a síntese individual.","Compare percepções em reuniões gerenciais."],"dicas":["Decisão esperada: definir prioridades de acompanhamento."]},{"titulo":"3. Performance","texto":"Confronte percepções com resultados.","passos":["Compare indicadores com o que foi dito nas entrevistas.","Considere carteira, território, clientes e produtos."],"dicas":["Decisão esperada: identificar causas prováveis dos resultados."]},{"titulo":"4. Visões Consolidadas","texto":"Identifique o que é padrão, o que é divergência e o que é situação individual.","passos":["Use em reuniões de gestão e diretoria.","Separe problemas estruturais de situações individuais."],"dicas":["Decisão esperada: definir prioridades corporativas."]},{"titulo":"5. BI Cliente","texto":"Entenda o papel de cada cliente no resultado do representante.","passos":["Acesse pelo menu de ações do cliente na Performance.","Analise concentração, retração e potencial."],"dicas":["Decisão esperada: definir clientes com plano de ação específico."]},{"titulo":"6. Price","texto":"Compare preços e avalie a competitividade do portfólio.","passos":["Analise comparativos e equivalências técnicas.","Considere posicionamento de marca e especificação."],"dicas":["Decisão esperada: definir produtos e condições que exigem revisão."]},{"titulo":"7. Gestão de Tarefas","texto":"Transforme descobertas em execução.","passos":["Registre tarefas com responsável, prazo e prioridade.","Vincule a tarefa à sua origem."],"dicas":["Decisão esperada: definir responsáveis, prazos e critérios de conclusão."]},{"titulo":"8. Ferramentas","texto":"Utilize tecnologia e automação para ampliar a capacidade de execução.","passos":["Selecione ferramentas conforme as prioridades da jornada.","Padronize processos repetitivos."],"dicas":["Conclusão: o ciclo gerencial completo, do contexto à execução."]}],"faq":[{"pergunta":"Onde encontro a trilha interativa?","resposta":"Na página inicial do sistema, em Guia de Uso Gerencial."},{"pergunta":"Preciso concluir a trilha para usar o sistema?","resposta":"Não. O guia é uma camada de orientação e fica sempre disponível em Ferramentas › Manuais."}]}'::jsonb
)
